const [liveStockRows] = useTable(tables.stock);
const frozenStockRows = useRef<typeof liveStockRows | null>(null);
if (frozenStockRows.current === null && liveStockRows.length > 0) {
  frozenStockRows.current = liveStockRows;
}
const stockRows = frozenStockRows.current ?? liveStockRows;

const [liveStockRows] = useTable(tables.stock);
const [freezeStockAfterOffline, setFreezeStockAfterOffline] = useState(false);
const lastOnlineStockRows = useRef(liveStockRows);
useEffect(() => {
  const freezeStock = () => setFreezeStockAfterOffline(true);
  window.addEventListener('offline', freezeStock);
  return () => window.removeEventListener('offline', freezeStock);
}, []);
if (!freezeStockAfterOffline) {
  lastOnlineStockRows.current = liveStockRows;
}
const stockRows = freezeStockAfterOffline ? lastOnlineStockRows.current : liveStockRows;
